    a1=max(y for t,y,z in ROWS if t<=b)
    a2=max(z for t,y,z in ROWS if t>=s or (t==F('.75') if s<F('.80') else t==F((100*s).__floor__(),100)))
    return ceil(coeff(b,a1,a2),10**8),ceil(slope(s),100)

