def opts(cap):
    for cs in choices(cap):
        T=terms(cs)
        j=ceil(max(M for b,m,c,M in T)+2,1)
        yield j,T
def minv(u,cap):
    return min([val(u,CH)]+[val(u,Q) for j,Q in opts(cap) if u>=j and u>=100]
        +([u*u*E(5*u/32)/64] if cap==B2 and u>=200 else []))

